    if(block.type==="choice"){const selected=state.choices[block.set||block.id],option=(block.options||[]).find(x=>x.value===selected),next=option?.gotoChapter&&b.chapters.find(x=>x.id===option.gotoChapter);return `<section class="choice" data-choice="${block.id}"><div class="choice-kicker">讀者選擇</div><p>${esc(block.prompt)}</p><div class="choice-options">${(block.options||[]).map((o,i)=>`<button data-option="${i}" class="${selected===o.value?"selected":""}">${esc(o.label)}</button>`).join("")}</div>${selected?`<p class="choice-result">${option?.result||""}</p>${next?`<button class="choice-continue" data-choice-next="${next.id}">繼續：${esc(next.title)} →</button>`:""}<p class="choice-feedback">你的選擇已記錄，並會影響此段後續內容。</p>`:""}</section>`}
    return "";
