  function bindFormatBubble(root){const bubble=$('[data-format-bubble]',root),editors=$$('.rich-editor',root);const show=()=>{const selection=getSelection();if(!selection||selection.isCollapsed||!editors.some(x=>x.contains(selection.anchorNode))){bubble.hidden=true;return}const rect=selection.getRangeAt(0).getBoundingClientRect();bubble.style.left=`${Math.max(12,rect.left)}px`;bubble.style.top=`${Math.max(10,rect.top-46)}px`;bubble.hidden=false};editors.forEach(editor=>{editor.addEventListener('mouseup',show);editor.addEventListener('keyup',show);editor.addEventListener('blur',()=>setTimeout(()=>{if(!bubble.matches(':hover'))bubble.hidden=true},120))});$$('[data-format]',bubble).forEach(button=>{button.addEventListener('mousedown',e=>e.preventDefault());button.addEventListener('click',()=>{document.execCommand(button.dataset.format,false);const active=document.activeElement;if(active?.classList.contains('rich-editor'))active.dispatchEvent(new Event('input',{bubbles:true}));bubble.hidden=true})})}
